const ts = require('/Users/stark/Desktop/work/RN/heals-app-rn/node_modules/typescript');
const path = require('path');
const {execSync} = require('child_process');

const repo = '/Users/stark/Desktop/work/RN/heals-app-rn';
const relFiles = [
  'src/components/questionnaire-widget/questionnaire-widget.tsx',
  'src/screens/plan-list-screen/plan-list-screen.styles.ts',
  'src/screens/plan-list-screen/plan-list-screen.tsx',
];

const configPath = path.join(repo, 'tsconfig.json');
const read = ts.readConfigFile(configPath, ts.sys.readFile);
if (read.error) {
  console.error('config error', read.error);
  process.exit(1);
}
const parsed = ts.parseJsonConfigFileContent(read.config, ts.sys, repo);
console.error('fileCount', parsed.fileNames.length, 'ts', ts.version);
if (parsed.errors && parsed.errors.length) {
  console.error('parse errors', parsed.errors.length);
}

const baseByNorm = new Map();
for (const rel of relFiles) {
  const text = execSync(`git show e3e0d1a:${rel}`, {cwd: repo, encoding: 'utf8'});
  baseByNorm.set(path.normalize(path.join(repo, rel)), text);
}

function collect(mode) {
  const host = ts.createCompilerHost(parsed.options, true);
  const origRead = host.readFile.bind(host);
  const origGet = host.getSourceFile.bind(host);
  if (mode === 'base') {
    host.readFile = (fileName) => {
      const hit = baseByNorm.get(path.normalize(fileName));
      if (hit != null) return hit;
      return origRead(fileName);
    };
    host.getSourceFile = (fileName, languageVersion, onError, shouldCreateNewSourceFile) => {
      const hit = baseByNorm.get(path.normalize(fileName));
      if (hit != null) {
        return ts.createSourceFile(fileName, hit, languageVersion, true, ts.ScriptKind.TSX);
      }
      return origGet(fileName, languageVersion, onError, shouldCreateNewSourceFile);
    };
  }
  const program = ts.createProgram({
    rootNames: parsed.fileNames,
    options: parsed.options,
    host,
  });
  const result = {};
  for (const rel of relFiles) {
    const abs = path.join(repo, rel);
    const sf = program.getSourceFile(abs) || program.getSourceFiles().find(s => s.fileName.endsWith(rel));
    if (!sf) {
      result[rel] = { missing: true, sample: program.getSourceFiles().slice(0, 3).map(s => s.fileName) };
      continue;
    }
    const fmt = (d) => {
      const pos = d.start != null ? sf.getLineAndCharacterOfPosition(d.start) : {line: 0, character: 0};
      return {
        code: 'TS' + d.code,
        category: ts.DiagnosticCategory[d.category],
        line: pos.line + 1,
        col: pos.character + 1,
        message: ts.flattenDiagnosticMessageText(d.messageText, '\n').slice(0, 300),
      };
    };
    let suggestion;
    let suggestionError;
    try {
      suggestion = typeof program.getSuggestionDiagnostics === 'function'
        ? program.getSuggestionDiagnostics(sf)
        : null;
    } catch (e) {
      suggestionError = String(e && e.stack || e);
    }
    result[rel] = {
      fileName: sf.fileName,
      syntactic: program.getSyntacticDiagnostics(sf).map(fmt),
      semantic: program.getSemanticDiagnostics(sf).map(fmt),
      suggestion: suggestion ? suggestion.map(fmt) : [],
      suggestionError: suggestionError || null,
      suggestionAvailable: typeof program.getSuggestionDiagnostics === 'function',
    };
  }
  return result;
}

const head = collect('head');
const base = collect('base');
const keyOf = (d) => `${d.code}|${d.category}|${d.message}`;
function diffDiags(a, b) {
  const count = (arr) => {
    const m = new Map();
    for (const d of arr) m.set(keyOf(d), (m.get(keyOf(d)) || 0) + 1);
    return m;
  };
  const ca = count(a);
  const cb = count(b);
  const added = [];
  for (const [k, n] of ca) {
    const baseN = cb.get(k) || 0;
    if (n > baseN) added.push({key: k, head: n, base: baseN});
  }
  return added;
}
const summary = {};
for (const rel of relFiles) {
  summary[rel] = {
    suggestionAvailable: head[rel].suggestionAvailable,
    suggestionError: head[rel].suggestionError,
    headCounts: {
      syntactic: head[rel].syntactic.length,
      semantic: head[rel].semantic.length,
      suggestion: head[rel].suggestion.length,
    },
    baseCounts: {
      syntactic: base[rel].syntactic.length,
      semantic: base[rel].semantic.length,
      suggestion: base[rel].suggestion.length,
    },
    addedSyntactic: diffDiags(head[rel].syntactic, base[rel].syntactic),
    addedSemantic: diffDiags(head[rel].semantic, base[rel].semantic),
    addedSuggestion: diffDiags(head[rel].suggestion, base[rel].suggestion),
    headSuggestionDeprecated: head[rel].suggestion.filter(d => d.code === 'TS6385' || d.code === 'TS6387' || /deprecat/i.test(d.message)),
    baseSuggestionDeprecated: base[rel].suggestion.filter(d => d.code === 'TS6385' || d.code === 'TS6387' || /deprecat/i.test(d.message)),
  };
}
console.log(JSON.stringify({summary, head, base}, null, 2));
EOF
